mapper.select:
select created_by, updated_by, created_at, updated_at from workflow
and workflow_code = #{workflowCode}
limit 1

select created_by, updated_by, created_at, updated_at from workflow
and (workflow_code like concat('%', #{keyword}, '%') or workflow_name like concat('%', #{keyword}, '%'))
order by id desc limit #{pageSize} offset #{offset}
